(function () {
    'use strict';
    var instances = [];
    var scrollBound = false;
    var ticking = false;
    var elementorHooked = false;
    var warnedScopes = {};
    var hashTimer = null;
    var hasPageBar = false;
    var hasPageRing = false;
    var fabDocClickBound = false;
    function t(key, fallback) {
        var str = (window.rawnaqSPT && window.rawnaqSPT.i18n && window.rawnaqSPT.i18n[key])
            ? window.rawnaqSPT.i18n[key]
            : (fallback || '');
        var args = Array.prototype.slice.call(arguments, 2);
        if (!args.length) {
            return str;
        }
        var idx = 0;
        str = str.replace(/%(\d+)\$([sdf])/g, function (match, num) {
            var n = parseInt(num, 10) - 1;
            return args[n] !== undefined ? args[n] : match;
        });
        str = str.replace(/%[sdf]/g, function () {
            var val = args[idx++];
            return val !== undefined ? val : '';
        });
        return str;
    }
    function prefersReducedMotion() {
        return !!(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches);
    }
    function getAdminBarHeight() {
        var bar = document.getElementById('wpadminbar');
        return (bar && bar.offsetHeight) ? bar.offsetHeight : 0;
    }
    var SVG_FAB_TRIGGER = '<svg viewBox="0 0 24 24" width="20" height="20" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" fill="none" aria-hidden="true"><line x1="3" y1="6" x2="21" y2="6"></line><line x1="3" y1="12" x2="21" y2="12"></line><line x1="3" y1="18" x2="21" y2="18"></line></svg>';
    var SVG_ACTION_TOC = '<svg viewBox="0 0 24 24" width="16" height="16" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" fill="none" aria-hidden="true"><path d="M4 19.5A2.5 2.5 0 0 1 6.5 17H20"></path><path d="M6.5 2H20v20H6.5A2.5 2.5 0 0 1 4 19.5v-15A2.5 2.5 0 0 1 6.5 2z"></path></svg>';
    var SVG_ACTION_TOP = '<svg viewBox="0 0 24 24" width="16" height="16" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" fill="none" aria-hidden="true"><polyline points="18 15 12 9 6 15"></polyline></svg>';
    var SVG_ACTION_COPY = '<svg viewBox="0 0 24 24" width="16" height="16" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" fill="none" aria-hidden="true"><path d="M10 13a5 5 0 0 0 7.54.54l3-3a5 5 0 0 0-7.07-7.07l-1.72 1.71"></path><path d="M14 11a5 5 0 0 0-7.54-.54l-3 3a5 5 0 0 0 7.07 7.07l1.71-1.71"></path></svg>';
    function setStaticSvg(el, svgHtml) {
        el.innerHTML = svgHtml;
    }
    function slugify(text, used) {
        var base = String(text || 'section').toLowerCase();
        try {
            base = base.replace(/[^\p{L}\p{N}\p{M}\s-]/gu, '');
        } catch (e) {
            base = base.replace(/[^\w\u0980-\u09FF\u0600-\u06FF\s-]/g, '');
        }
        base = base.trim().replace(/\s+/g, '-');
        if (!base) {
            base = 'section';
        }
        var id = base;
        var n = 2;
        while (used[id] || document.getElementById(id)) {
            id = base + '-' + n;
            n++;
        }
        used[id] = true;
        return id;
    }
    function parseCfg(el) {
        try {
            return JSON.parse(el.getAttribute('data-spt') || '{}');
        } catch (e) {
            return {};
        }
    }
    function resolveScope(userScope) {
        if (userScope && typeof userScope === 'string') {
            var trimmed = userScope.trim();
            if (trimmed) {
                try {
                    var el = document.querySelector(trimmed);
                    if (el) {
                        return el;
                    }
                } catch (e) {}
                if (!warnedScopes[trimmed]) {
                    warnedScopes[trimmed] = true;
                    console.warn('[Rawnaq SPT] Invalid or missing scope selector: "' + trimmed + '". Falling back.');
                }
            }
        }
        var fallbacks = ['.entry-content', 'article', '.wp-block-post-content', 'main', 'body'];
        for (var i = 0; i < fallbacks.length; i++) {
            try {
                var found = document.querySelector(fallbacks[i]);
                if (found) {
                    return found;
                }
            } catch (err) {}
        }
        return document.body;
    }
    function getProgressElement(inst) {
        if (!inst || !inst.cfg) {
            return null;
        }
        var targetMode = inst.cfg.progressTarget || 'page';
        if (targetMode === 'article') {
            var articleSel = inst.cfg.scope || '.entry-content, article, .wp-block-post-content, main';
            try {
                return document.querySelector(articleSel) || null;
            } catch (e) {
                return null;
            }
        }
        if (targetMode === 'custom' && inst.cfg.progressSelector) {
            try {
                return document.querySelector(inst.cfg.progressSelector) || null;
            } catch (e) {
                return null;
            }
        }
        return null;
    }
    function getScrollProgress(inst) {
        var doc = document.documentElement;
        var scrollTop = window.pageYOffset || doc.scrollTop || 0;
        var targetEl = getProgressElement(inst);
        if (targetEl) {
            var rect = targetEl.getBoundingClientRect();
            var targetTop = rect.top + scrollTop;
            var targetHeight = targetEl.offsetHeight || rect.height;
            var viewportHeight = window.innerHeight;
            var scrollable = targetHeight - viewportHeight;
            if (scrollable <= 0) {
                return scrollTop >= targetTop ? 1 : 0;
            }
            return Math.max(0, Math.min(1, (scrollTop - targetTop) / scrollable));
        }
        var height = Math.max(doc.scrollHeight - window.innerHeight, 1);
        return Math.max(0, Math.min(1, scrollTop / height));
    }
    function updateProgress(inst) {
        var p = getScrollProgress(inst);
        if (inst.barFill) {
            inst.barFill.style.width = (p * 100) + '%';
        }
        if (inst.ringFg) {
            var circ = 126;
            inst.ringFg.style.strokeDashoffset = String(circ * (1 - p));
        }
        if (inst.ringLabel) {
            inst.ringLabel.textContent = Math.round(p * 100) + '%';
        }
        if (inst.ring) {
            if (p > 0.05) {
                inst.ring.classList.add('is-visible');
            } else {
                inst.ring.classList.remove('is-visible');
            }
        }
        if (inst.cfg.readingTime && inst.totalMins) {
            var readEl = inst.root.querySelector('.rawnaq-spt-reading');
            if (readEl) {
                var minsRemaining = Math.max(1, Math.round(inst.totalMins * (1 - p)));
                if (p >= 0.96) {
                    readEl.textContent = t('finishedReading', 'Finished reading');
                } else {
                    readEl.textContent = t('minLeft', '%s min left', minsRemaining);
                }
            }
        }
        if (inst.root) {
            var short = document.documentElement.scrollHeight <= window.innerHeight + 40;
            inst.root.classList.toggle('is-hidden', short && !!inst.cfg.hideIfShort);
        }
    }
    function updateActiveIndicator(tocEl) {
        var activeLink = tocEl.querySelector('.rawnaq-spt-list a.is-active');
        var indicator = tocEl.querySelector('.rawnaq-spt-indicator');
        var listWrap = tocEl.querySelector('.rawnaq-spt-list-wrap');
        if (!indicator) {
            return;
        }
        if (activeLink && activeLink.offsetParent !== null && listWrap) {
            var wrapRect = listWrap.getBoundingClientRect();
            var linkRect = activeLink.getBoundingClientRect();
            var top = linkRect.top - wrapRect.top + listWrap.scrollTop;
            indicator.style.opacity = '1';
            indicator.style.transform = 'translateY(' + top + 'px)';
            indicator.style.height = linkRect.height + 'px';
        } else {
            indicator.style.opacity = '0';
        }
    }
    function estimateReadingTime(scope, wpm) {
        wpm = parseInt(wpm, 10) || 200;
        if (!scope) {
            scope = document.querySelector('.entry-content, article, .wp-block-post-content, main, body');
        }
        if (!scope) {
            return 1;
        }
        var clone = scope.cloneNode(true);
        var toRemove = clone.querySelectorAll('.rawnaq-spt, nav, aside, #comments, .comments-area, script, style');
        toRemove.forEach(function (el) {
            if (el.parentNode) {
                el.parentNode.removeChild(el);
            }
        });
        var text = clone.textContent || '';
        var cjkMatch = text.match(/[\u4e00-\u9fff\u3400-\u4dbf\uF900-\uFAFF\u3040-\u30ff\uac00-\ud7af]/g);
        var cjkCount = cjkMatch ? cjkMatch.length : 0;
        var nonCjkText = text.replace(/[\u4e00-\u9fff\u3400-\u4dbf\uF900-\uFAFF\u3040-\u30ff\uac00-\ud7af]/g, ' ');
        var words = nonCjkText.split(/\s+/).filter(Boolean).length;
        var totalMins = (words / wpm) + (cjkCount / 500);
        return Math.max(1, Math.round(totalMins));
    }
    function collectHeadings(cfg) {
        var levels = cfg.levels || ['h2', 'h3'];
        var selector = levels.map(function (l) { return l.toLowerCase(); }).join(',');
        if (!selector) {
            return [];
        }
        var scope = resolveScope(cfg.scope);
        var nodes = scope.querySelectorAll(selector);
        var used = {};
        var items = [];
        var currentParent = null;
        var offset = (parseInt(cfg.scrollOffset, 10) || 80) + getAdminBarHeight();
        var wpm = parseInt(cfg.wpm, 10) || 200;
        nodes.forEach(function (h, idx) {
            if (h.closest && h.closest('.rawnaq-spt')) {
                return;
            }
            var text = (h.textContent || '').trim();
            if (!text) {
                return;
            }
            if (!h.id) {
                h.id = slugify(text, used);
            } else {
                used[h.id] = true;
            }
            if (!h.style.scrollMarginTop) {
                h.style.scrollMarginTop = offset + 'px';
            }
            var lvl = parseInt(h.tagName.replace('H', ''), 10) || 2;
            if (lvl === 2) {
                currentParent = h.id;
            }
            var secWords = 0;
            var secCjk = 0;
            var nextNode = nodes[idx + 1];
            var walker = h.nextElementSibling;
            while (walker && walker !== nextNode && walker !== h) {
                var wText = walker.textContent || '';
                var cjkM = wText.match(/[\u4e00-\u9fff\u3400-\u4dbf\uF900-\uFAFF\u3040-\u30ff\uac00-\ud7af]/g);
                secCjk += cjkM ? cjkM.length : 0;
                var nonC = wText.replace(/[\u4e00-\u9fff\u3400-\u4dbf\uF900-\uFAFF\u3040-\u30ff\uac00-\ud7af]/g, ' ');
                secWords += nonC.split(/\s+/).filter(Boolean).length;
                walker = walker.nextElementSibling;
            }
            var secMins = Math.max(1, Math.round((secWords / wpm) + (secCjk / 500)));
            items.push({
                id: h.id,
                text: text,
                level: lvl,
                el: h,
                parentH2: lvl > 2 ? currentParent : null,
                secMins: secMins
            });
        });
        return items;
    }
    function manualItems(cfg) {
        var currentParent = null;
        var offset = (parseInt(cfg.scrollOffset, 10) || 80) + getAdminBarHeight();
        return (cfg.manual || []).map(function (m, i) {
            var lvl = parseInt(m.level, 10) || 2;
            var id = m.id || ('spt-m-' + i);
            if (lvl === 2) {
                currentParent = id;
            }
            var targetEl = document.getElementById(m.id) || null;
            if (targetEl && !targetEl.style.scrollMarginTop) {
                targetEl.style.scrollMarginTop = offset + 'px';
            }
            return {
                id: id,
                text: m.title || '',
                level: lvl,
                el: targetEl,
                parentH2: lvl > 2 ? currentParent : null,
                secMins: 1
            };
        }).filter(function (m) { return m.text; });
    }
    function syncUrlHash(id, immediate) {
        if (!id) {
            return;
        }
        var update = function () {
            if (window.location.hash !== ('#' + id)) {
                try {
                    history.replaceState(null, null, '#' + id);
                } catch (e) {}
            }
        };
        if (immediate) {
            if (hashTimer) {
                clearTimeout(hashTimer);
                hashTimer = null;
            }
            update();
        } else {
            if (hashTimer) {
                clearTimeout(hashTimer);
            }
            hashTimer = setTimeout(update, 300);
        }
    }
    function buildTocList(tocEl, items, cfg) {
        var listWrap = tocEl.querySelector('.rawnaq-spt-list-wrap');
        var list = tocEl.querySelector('.rawnaq-spt-list');
        if (!list) {
            return;
        }
        if (!listWrap) {
            listWrap = document.createElement('div');
            listWrap.className = 'rawnaq-spt-list-wrap';
            list.parentNode.insertBefore(listWrap, list);
            listWrap.appendChild(list);
        }
        var isSSR = (list.getAttribute('data-ssr') === '1') || (list.children.length > 0 && !!list.querySelector('a'));
        var offset = (parseInt(cfg.scrollOffset, 10) || 80) + getAdminBarHeight();
        var existingIndicator = listWrap.querySelector('.rawnaq-spt-indicator');
        if (!existingIndicator) {
            var indicator = document.createElement('span');
            indicator.className = 'rawnaq-spt-indicator';
            indicator.setAttribute('aria-hidden', 'true');
            listWrap.appendChild(indicator);
        }
        var allLinks = [];
        function wireLink(a, targetId) {
            function scrollToTarget(e) {
                var target = document.getElementById(targetId);
                if (!target) {
                    return;
                }
                if (e) {
                    e.preventDefault();
                }
                var curOffset = (parseInt(cfg.scrollOffset, 10) || 80) + getAdminBarHeight();
                var top = target.getBoundingClientRect().top + window.pageYOffset - curOffset;
                if (prefersReducedMotion() || cfg.smooth === false) {
                    window.scrollTo(0, top);
                } else {
                    window.scrollTo({ top: top, behavior: 'smooth' });
                }
                target.setAttribute('tabindex', '-1');
                target.focus({ preventScroll: true });
                tocEl.classList.remove('is-sheet-open');
                if (cfg.urlHashSync) {
                    syncUrlHash(targetId, true);
                }
            }
            a.addEventListener('click', scrollToTarget);
            a.addEventListener('keydown', function (e) {
                if (e.key === 'Enter' || e.key === ' ') {
                    e.preventDefault();
                    scrollToTarget(e);
                } else if (e.key === 'ArrowDown' || e.key === 'ArrowUp' || e.key === 'Home' || e.key === 'End') {
                    var visibleLinks = allLinks.filter(function (link) {
                        return link.offsetParent !== null;
                    });
                    var curIdx = visibleLinks.indexOf(a);
                    if (curIdx === -1) {
                        return;
                    }
                    if (e.key === 'ArrowDown') {
                        e.preventDefault();
                        if (curIdx < visibleLinks.length - 1) {
                            visibleLinks[curIdx + 1].focus();
                        }
                    } else if (e.key === 'ArrowUp') {
                        e.preventDefault();
                        if (curIdx > 0) {
                            visibleLinks[curIdx - 1].focus();
                        }
                    } else if (e.key === 'Home') {
                        e.preventDefault();
                        if (visibleLinks.length > 0) {
                            visibleLinks[0].focus();
                        }
                    } else if (e.key === 'End') {
                        e.preventDefault();
                        if (visibleLinks.length > 0) {
                            visibleLinks[visibleLinks.length - 1].focus();
                        }
                    }
                }
            });
        }
        if (isSSR) {
            var existingLis = list.querySelectorAll('li');
            existingLis.forEach(function (li) {
                var a = li.querySelector('a');
                if (!a) return;
                var href = a.getAttribute('href') || '';
                var targetId = href.replace(/^#/, '');
                var it = items.find(function (item) { return item.id === targetId; });
                if (it) {
                    it.link = a;
                    it.liElement = li;
                    if (it.level > 2 && cfg.collapseSubs) {
                        li.classList.add('is-collapsed-child');
                        if (it.parentH2) {
                            li.setAttribute('data-parent-h2', it.parentH2);
                        }
                    }
                    if (cfg.sectionReadingTime && it.level === 2 && it.secMins > 0 && !a.querySelector('.rawnaq-spt-sec-badge')) {
                        var timeBadge = document.createElement('span');
                        timeBadge.className = 'rawnaq-spt-sec-badge';
                        timeBadge.textContent = t('secBadge', '~%sm', it.secMins);
                        timeBadge.setAttribute('title', t('secTitle', 'Estimated %s min section', it.secMins));
                        a.appendChild(timeBadge);
                    }
                }
                wireLink(a, targetId);
                allLinks.push(a);
            });
        } else {
            list.innerHTML = '';
            items.forEach(function (it) {
                var li = document.createElement('li');
                li.className = 'lvl-' + it.level;
                if (it.level > 2 && cfg.collapseSubs) {
                    li.classList.add('is-collapsed-child');
                    if (it.parentH2) {
                        li.setAttribute('data-parent-h2', it.parentH2);
                    }
                }
                var a = document.createElement('a');
                a.href = '#' + it.id;
                a.className = 'lvl-' + it.level;
                var textSpan = document.createElement('span');
                textSpan.className = 'rawnaq-spt-link-text';
                textSpan.textContent = it.text;
                a.appendChild(textSpan);
                if (cfg.sectionReadingTime && it.level === 2 && it.secMins > 0) {
                    var timeBadge = document.createElement('span');
                    timeBadge.className = 'rawnaq-spt-sec-badge';
                    timeBadge.textContent = t('secBadge', '~%sm', it.secMins);
                    timeBadge.setAttribute('title', t('secTitle', 'Estimated %s min section', it.secMins));
                    a.appendChild(timeBadge);
                }
                wireLink(a, it.id);
                li.appendChild(a);
                list.appendChild(li);
                it.link = a;
                it.liElement = li;
                allLinks.push(a);
            });
        }
        if (cfg.showSearch) {
            var existingSearch = tocEl.querySelector('.rawnaq-spt-search-wrap');
            if (existingSearch) {
                existingSearch.parentNode.removeChild(existingSearch);
            }
            var searchBox = document.createElement('div');
            searchBox.className = 'rawnaq-spt-search-wrap';
            var searchInput = document.createElement('input');
            searchInput.type = 'search';
            searchInput.className = 'rawnaq-spt-search-input';
            searchInput.placeholder = t('searchPlaceholder', 'Search headings...');
            searchInput.setAttribute('aria-label', t('searchAriaLabel', 'Search headings'));
            searchBox.appendChild(searchInput);
            var insertBeforeNode = listWrap || list;
            tocEl.insertBefore(searchBox, insertBeforeNode);
            searchInput.addEventListener('input', function (e) {
                var q = e.target.value.toLowerCase().trim();
                var listItems = list.querySelectorAll('li');
                listItems.forEach(function (li) {
                    var text = li.textContent.toLowerCase();
                    if (!q) {
                        if (li.classList.contains('lvl-3') || li.classList.contains('lvl-4')) {
                            if (!cfg.collapseSubs) {
                                li.style.display = '';
                            }
                        } else {
                            li.style.display = '';
                        }
                        return;
                    }
                    if (text.indexOf(q) !== -1) {
                        li.style.display = '';
                        li.classList.remove('is-collapsed-child');
                    } else {
                        li.style.display = 'none';
                    }
                });
                updateActiveIndicator(tocEl);
            });
        }
    }
    function updateActiveSection(inst) {
        if (!inst.items || !inst.items.length || !inst.toc) {
            return;
        }
        var items = inst.items;
        var tocEl = inst.toc;
        var cfg = inst.cfg;
        var offset = (parseInt(cfg.scrollOffset, 10) || 80) + getAdminBarHeight();
        var doc = document.documentElement;
        var scrollTop = window.pageYOffset || doc.scrollTop || 0;
        var isAtBottom = (scrollTop + window.innerHeight >= doc.scrollHeight - 2);
        var activeItem = null;
        if (isAtBottom) {
            activeItem = items[items.length - 1];
        } else {
            for (var i = items.length - 1; i >= 0; i--) {
                var el = items[i].el;
                if (el) {
                    var top = el.getBoundingClientRect().top;
                    if (top <= offset + 1) {
                        activeItem = items[i];
                        break;
                    }
                }
            }
            if (!activeItem && items[0] && items[0].el) {
                var firstTop = items[0].el.getBoundingClientRect().top;
                if (firstTop < window.innerHeight && firstTop >= 0) {
                    activeItem = items[0];
                }
            }
        }
        var activeId = activeItem ? activeItem.id : null;
        var activeParent = activeItem ? (activeItem.parentH2 || activeItem.id) : null;
        var searchInput = tocEl.querySelector('.rawnaq-spt-search-input');
        var isSearching = searchInput && searchInput.value.trim().length > 0;
        items.forEach(function (it) {
            var isActive = (activeId && it.id === activeId);
            if (it.link) {
                it.link.classList.toggle('is-active', isActive);
                if (isActive) {
                    it.link.setAttribute('aria-current', 'true');
                } else {
                    it.link.removeAttribute('aria-current');
                }
            }
            if (it.liElement && it.level > 2 && cfg.collapseSubs && !isSearching) {
                if (activeParent && it.parentH2 === activeParent) {
                    it.liElement.classList.remove('is-collapsed-child');
                    it.liElement.style.display = '';
                } else {
                    it.liElement.classList.add('is-collapsed-child');
                    it.liElement.style.display = 'none';
                }
            }
        });
        updateActiveIndicator(tocEl);
        if (cfg.urlHashSync && activeId) {
            syncUrlHash(activeId, false);
        }
    }
    function fallbackCopy(text) {
        var ta = document.createElement('textarea');
        ta.value = text;
        ta.style.position = 'fixed';
        ta.style.left = '-9999px';
        ta.style.top = '0';
        ta.setAttribute('readonly', '');
        document.body.appendChild(ta);
        ta.select();
        try {
            document.execCommand('copy');
        } catch (err) {}
        document.body.removeChild(ta);
    }
    function onScroll() {
        if (ticking) {
            return;
        }
        ticking = true;
        window.requestAnimationFrame(function () {
            instances.forEach(function (inst) {
                updateProgress(inst);
                updateActiveSection(inst);
            });
            ticking = false;
        });
    }
    function handleInitialHash() {
        if (!window.location.hash) {
            return;
        }
        var hashId = window.location.hash.substring(1);
        if (!hashId) {
            return;
        }
        var target = document.getElementById(hashId);
        if (!target) {
            return;
        }
        var matched = instances.some(function (inst) {
            return inst.items && inst.items.some(function (it) { return it.id === hashId; });
        });
        if (matched) {
            var offset = 80 + getAdminBarHeight();
            if (instances[0] && instances[0].cfg && instances[0].cfg.scrollOffset) {
                offset = parseInt(instances[0].cfg.scrollOffset, 10) + getAdminBarHeight();
            }
            var top = target.getBoundingClientRect().top + window.pageYOffset - offset;
            window.scrollTo(0, top);
        }
    }
    function bindScroll() {
        if (scrollBound) {
            return;
        }
        window.addEventListener('scroll', onScroll, { passive: true });
        window.addEventListener('resize', onScroll, { passive: true });
        window.addEventListener('load', function () {
            instances.forEach(function (inst) {
                updateProgress(inst);
                updateActiveSection(inst);
            });
            handleInitialHash();
        });
        scrollBound = true;
    }
    function bindTimelineSync(inst, tlName) {
        var name = String(tlName || '').replace(/[^a-zA-Z0-9_-]/g, '');
        if (!name || !inst.chapterEl) {
            return;
        }
        var wrap = document.querySelector('.rawnaq-timeline-wrapper[data-tl-name="' + name + '"]');
        if (!wrap) {
            return;
        }
        function refresh() {
            var active = wrap.querySelector('.rawnaq-timeline-item.item-active');
            if (!active) {
                inst.chapterEl.hidden = true;
                return;
            }
            var title = '';
            var h = active.querySelector('h4, h3, .rawnaq-timeline-title');
            if (h) {
                title = (h.textContent || '').trim();
            }
            var items = wrap.querySelectorAll('.rawnaq-timeline-item');
            var idx = 0;
            for (var i = 0; i < items.length; i++) {
                if (items[i] === active) {
                    idx = i + 1;
                    break;
                }
            }
            inst.chapterEl.hidden = false;
            inst.chapterEl.textContent = title
                ? t('chapterNTitle', 'Chapter %1$s: %2$s', idx, title)
                : t('chapterN', 'Chapter %s', idx);
        }
        refresh();
        if (typeof MutationObserver === 'undefined') {
            return;
        }
        var mo = new MutationObserver(refresh);
        mo.observe(wrap, { attributes: true, attributeFilter: ['class'], subtree: true });
        inst.timelineMo = mo;
    }
    function onFabDocClick(e) {
        var trigger = e.target.closest('.rawnaq-spt-fab-trigger');
        if (trigger) {
            var wrapper = trigger.closest('.rawnaq-spt-fab-wrapper');
            if (wrapper) {
                var active = wrapper.classList.toggle('is-active');
                trigger.setAttribute('aria-expanded', active ? 'true' : 'false');
                return;
            }
        }
        if (!e.target.closest('.rawnaq-spt-fab-wrapper')) {
            document.querySelectorAll('.rawnaq-spt-fab-wrapper.is-active').forEach(function (w) {
                w.classList.remove('is-active');
                var tr = w.querySelector('.rawnaq-spt-fab-trigger');
                if (tr) tr.setAttribute('aria-expanded', 'false');
            });
        }
    }
    function bindFabDocClick() {
        if (fabDocClickBound) {
            return;
        }
        document.addEventListener('click', onFabDocClick);
        fabDocClickBound = true;
    }
    function destroyAll() {
        instances.forEach(function (inst) {
            if (inst.timelineMo) {
                inst.timelineMo.disconnect();
            }
            if (inst.resizeObserver) {
                inst.resizeObserver.disconnect();
            }
            if (inst.dockMo) {
                inst.dockMo.disconnect();
            }
            if (inst.bar && inst.bar.parentNode) {
                inst.bar.parentNode.removeChild(inst.bar);
            }
            if (inst.ring && inst.ring.parentNode) {
                inst.ring.parentNode.removeChild(inst.ring);
            }
            if (inst.dockItem && inst.dockItem.parentNode) {
                inst.dockItem.parentNode.removeChild(inst.dockItem);
            }
            if (inst.fabWrapper && inst.fabWrapper.parentNode) {
                inst.fabWrapper.parentNode.removeChild(inst.fabWrapper);
            }
            if (inst.root) {
                inst.root.classList.remove('spt-bound', 'is-dock-attached');
            }
        });
        instances = [];
        hasPageBar = false;
        hasPageRing = false;
        if (fabDocClickBound) {
            document.removeEventListener('click', onFabDocClick);
            fabDocClickBound = false;
        }
    }
    function initOne(root) {
        if (!root || root.classList.contains('spt-bound')) {
            return;
        }
        for (var i = 0; i < instances.length; i++) {
            if (instances[i].root === root) {
                return;
            }
        }
        var inst = {
            root: root,
            cfg: null,
            bar: null,
            barFill: null,
            ring: null,
            ringFg: null,
            ringLabel: null,
            dockItem: null,
            fabWrapper: null,
            items: [],
            toc: null,
            resizeObserver: null,
            timelineMo: null,
            dockMo: null
        };
        try {
            var cfg = parseCfg(root);
            cfg.hideIfShort = cfg.hideIfShort !== false;
            cfg.clickToTop = cfg.clickToTop !== false;
            cfg.tocCollapsible = cfg.tocCollapsible !== false;
            inst.cfg = cfg;
            var progress = cfg.progress || 'both';
            var tocPos = cfg.tocPosition || 'sticky';
            var showToc = tocPos !== 'none';
            if (progress === 'bar' || progress === 'both') {
                if (!hasPageBar) {
                    var bar = document.createElement('div');
                    bar.className = 'rawnaq-spt-bar' + (cfg.barPosition === 'bottom' ? ' is-bottom' : '');
                    bar.innerHTML = '<span class="rawnaq-spt-bar-fill"></span>';
                    document.body.appendChild(bar);
                    inst.bar = bar;
                    inst.barFill = bar.querySelector('.rawnaq-spt-bar-fill');
                    hasPageBar = true;
                } else if (cfg.debug) {
                    console.info('[Rawnaq SPT] Progress bar already exists on page. Skipping duplicate.');
                }
            }
            if (progress === 'ring' || progress === 'both') {
                if (!hasPageRing) {
                    var ring = document.createElement('div');
                    ring.className = 'rawnaq-spt-ring' + (cfg.clickToTop ? ' is-clickable' : '');
                    if (cfg.clickToTop) {
                        ring.setAttribute('role', 'button');
                        ring.setAttribute('tabindex', '0');
                        ring.setAttribute('aria-label', t('scrollToTop', 'Scroll to top of page'));
                        ring.setAttribute('title', t('backToTop', 'Back to top'));
                    }
                    ring.innerHTML = '<svg viewBox="0 0 48 48" aria-hidden="true">'
                        + '<circle class="rawnaq-spt-ring-bg" cx="24" cy="24" r="20"></circle>'
                        + '<circle class="rawnaq-spt-ring-fg" cx="24" cy="24" r="20"></circle>'
                        + '<path class="rawnaq-spt-ring-arrow" d="M24 14 L16 22 L18.5 24.5 L22.2 20.8 L22.2 34 L25.8 34 L25.8 20.8 L29.5 24.5 L32 22 Z" />'
                        + '</svg>'
                        + (cfg.showPercent !== false ? '<span class="rawnaq-spt-ring-label">0%</span>' : '');
                    var ringSize = (getComputedStyle(root).getPropertyValue('--spt-ring-size') || '').trim();
                    if (ringSize) {
                        ring.style.setProperty('--spt-ring-size', ringSize);
                    }
                    document.body.appendChild(ring);
                    inst.ring = ring;
                    inst.ringFg = ring.querySelector('.rawnaq-spt-ring-fg');
                    inst.ringLabel = ring.querySelector('.rawnaq-spt-ring-label');
                    hasPageRing = true;
                    if (cfg.clickToTop) {
                        var doScrollTop = function (e) {
                            e.preventDefault();
                            window.scrollTo({ top: 0, behavior: prefersReducedMotion() ? 'auto' : 'smooth' });
                        };
                        ring.addEventListener('click', doScrollTop);
                        ring.addEventListener('keydown', function (e) {
                            if (e.key === 'Enter' || e.key === ' ') {
                                doScrollTop(e);
                            }
                        });
                    }
                } else if (cfg.debug) {
                    console.info('[Rawnaq SPT] Progress ring already exists on page. Skipping duplicate.');
                }
            }
            var items = [];
            if (showToc) {
                if (cfg.source === 'manual') {
                    items = manualItems(cfg);
                } else {
                    items = collectHeadings(cfg);
                }
                var toc = root.querySelector('.rawnaq-spt-toc');
                if (!toc) {
                    var listId = 'spt-list-' + Math.random().toString(36).substring(2, 9);
                    toc = document.createElement('nav');
                    toc.className = 'rawnaq-spt-toc';
                    toc.setAttribute('aria-label', cfg.tocTitle || t('contents', 'Contents'));
                    toc.innerHTML = '<div class="rawnaq-spt-header-wrap">'
                        + '<p class="rawnaq-spt-reading" hidden></p>'
                        + '<div class="rawnaq-spt-title-row"><h3 class="rawnaq-spt-title"></h3></div>'
                        + '</div>'
                        + '<div class="rawnaq-spt-list-wrap" id="' + listId + '">'
                        + '<ul class="rawnaq-spt-list"></ul>'
                        + '</div>';
                    root.appendChild(toc);
                }
                inst.toc = toc;
                inst.items = items;
                toc.classList.add('is-' + tocPos);
                if (cfg.mobileCollapse !== false && (tocPos === 'sticky' || tocPos === 'floating')) {
                    toc.classList.add('collapse-mobile');
                    root.classList.add('has-mobile-fab');
                }
                if (cfg.collapseSubs) {
                    toc.classList.remove('is-expanded');
                } else {
                    toc.classList.add('is-expanded');
                }
                var titleRow = toc.querySelector('.rawnaq-spt-title-row');
                var titleEl = toc.querySelector('.rawnaq-spt-title');
                if (titleEl) {
                    titleEl.textContent = cfg.tocTitle || t('contents', 'Contents');
                }
                var listWrap = toc.querySelector('.rawnaq-spt-list-wrap');
                var targetListId = (listWrap && listWrap.id) ? listWrap.id : '';
                if (cfg.tocCollapsible && titleRow) {
                    var toggleBtn = titleRow.querySelector('.rawnaq-spt-toggle-btn');
                    if (!toggleBtn) {
                        toggleBtn = document.createElement('button');
                        toggleBtn.type = 'button';
                        toggleBtn.className = 'rawnaq-spt-toggle-btn';
                        toggleBtn.setAttribute('aria-expanded', 'true');
                        if (targetListId) {
                            toggleBtn.setAttribute('aria-controls', targetListId);
                        }
                        toggleBtn.setAttribute('aria-label', t('toggleToc', 'Toggle Table of Contents'));
                        toggleBtn.innerHTML = '<svg viewBox="0 0 24 24" width="16" height="16" stroke="currentColor" stroke-width="2.5" fill="none" aria-hidden="true"><polyline points="6 9 12 15 18 9"></polyline></svg>';
                        titleRow.appendChild(toggleBtn);
                    } else if (targetListId && !toggleBtn.getAttribute('aria-controls')) {
                        toggleBtn.setAttribute('aria-controls', targetListId);
                    }
                    var toggleTocCollapse = function (e) {
                        e.stopPropagation();
                        var isClosed = toc.classList.toggle('is-toc-collapsed');
                        toggleBtn.setAttribute('aria-expanded', isClosed ? 'false' : 'true');
                        updateActiveIndicator(toc);
                    };
                    toggleBtn.addEventListener('click', toggleTocCollapse);
                    titleRow.addEventListener('click', toggleTocCollapse);
                    titleRow.style.cursor = 'pointer';
                }
                if (cfg.readingTime) {
                    var readEl = toc.querySelector('.rawnaq-spt-reading');
                    if (readEl) {
                        var scopeEl = resolveScope(cfg.scope);
                        var mins = estimateReadingTime(scopeEl, cfg.wpm);
                        inst.totalMins = mins;
                        readEl.hidden = false;
                        readEl.textContent = t('minRead', '%s min read', mins);
                    }
                }
                var chapterEl = toc.querySelector('.rawnaq-spt-chapter');
                if (!chapterEl) {
                    chapterEl = document.createElement('p');
                    chapterEl.className = 'rawnaq-spt-chapter';
                    chapterEl.hidden = true;
                    var headerWrap = toc.querySelector('.rawnaq-spt-header-wrap');
                    if (headerWrap) {
                        headerWrap.insertBefore(chapterEl, headerWrap.firstChild);
                    } else {
                        toc.insertBefore(chapterEl, toc.firstChild);
                    }
                }
                inst.chapterEl = chapterEl;
                if (cfg.syncTimeline) {
                    bindTimelineSync(inst, cfg.syncTimeline);
                }
                buildTocList(toc, items, cfg);
                if (window.ResizeObserver) {
                    inst.resizeObserver = new ResizeObserver(function () {
                        updateActiveIndicator(toc);
                    });
                    inst.resizeObserver.observe(toc);
                }
                var dockAttached = false;
                var tryDockAttach = function () {
                    if (dockAttached || !cfg.dockAttach || tocPos !== 'floating') {
                        return false;
                    }
                    var dock = document.querySelector('.rawnaq-dock-container');
                    if (!dock) {
                        return false;
                    }
                    var existing = dock.querySelector('.rawnaq-dock-item.is-toc-trigger');
                    if (existing) {
                        inst.dockItem = existing;
                        dockAttached = true;
                        root.classList.add('is-dock-attached');
                        toc.classList.add('dock-attached');
                        return true;
                    }
                    var titleText = cfg.tocTitle || t('contents', 'Contents');
                    var dockBtn = document.createElement('button');
                    dockBtn.type = 'button';
                    dockBtn.className = 'rawnaq-dock-item is-toc-trigger';
                    dockBtn.setAttribute('aria-label', titleText);
                    dockBtn.setAttribute('aria-expanded', 'false');
                    dockBtn.style.setProperty('--hover-color', '#4338ca');
                    var iconSpan = document.createElement('span');
                    iconSpan.className = 'rawnaq-dock-icon';
                    iconSpan.setAttribute('aria-hidden', 'true');
                    iconSpan.innerHTML = '<svg viewBox="0 0 24 24" width="18" height="18" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" fill="none" aria-hidden="true"><line x1="3" y1="6" x2="21" y2="6"></line><line x1="3" y1="12" x2="21" y2="12"></line><line x1="3" y1="18" x2="21" y2="18"></line></svg>';
                    var tooltipSpan = document.createElement('span');
                    tooltipSpan.className = 'rawnaq-dock-tooltip';
                    tooltipSpan.textContent = titleText;
                    var mobileLabelSpan = document.createElement('span');
                    mobileLabelSpan.className = 'rawnaq-dock-mobile-label';
                    mobileLabelSpan.textContent = titleText;
                    dockBtn.appendChild(iconSpan);
                    dockBtn.appendChild(tooltipSpan);
                    dockBtn.appendChild(mobileLabelSpan);
                    dock.appendChild(dockBtn);
                    dockBtn.addEventListener('click', function (e) {
                        e.preventDefault();
                        e.stopPropagation();
                        var open = toc.classList.toggle('is-panel-open');
                        dockBtn.classList.toggle('is-active', open);
                        dockBtn.setAttribute('aria-expanded', open ? 'true' : 'false');
                    });
                    inst.dockItem = dockBtn;
                    dockAttached = true;
                    root.classList.add('is-dock-attached');
                    toc.classList.add('dock-attached');
                    var dockOffset = getComputedStyle(dock).getPropertyValue('--dock-safe-offset') || '0px';
                    var dockBottom = getComputedStyle(dock).getPropertyValue('--dock-offset') || '20px';
                    root.style.setProperty('--spt-dock-clear', 'calc(' + dockBottom.trim() + ' + ' + dockOffset.trim() + ' + 72px)');
                    var existingFab = root.querySelector('.rawnaq-spt-fab-wrapper');
                    if (existingFab) {
                        existingFab.hidden = true;
                        existingFab.style.display = 'none';
                    }
                    return true;
                };
                if (cfg.dockAttach && tocPos === 'floating') {
                    if (!tryDockAttach()) {
                        var dockTimeout = null;
                        var dockMo = new MutationObserver(function () {
                            if (tryDockAttach()) {
                                dockMo.disconnect();
                                if (dockTimeout) clearTimeout(dockTimeout);
                            }
                        });
                        dockMo.observe(document.body, { childList: true, subtree: true });
                        dockTimeout = setTimeout(function () {
                            dockMo.disconnect();
                        }, 5000);
                        inst.dockMo = dockMo;
                    }
                }
                var fabWrapper = root.querySelector('.rawnaq-spt-fab-wrapper');
                if (!dockAttached && !fabWrapper && root.classList.contains('has-mobile-fab')) {
                    fabWrapper = document.createElement('div');
                    fabWrapper.className = 'rawnaq-spt-fab-wrapper';
                    var triggerBtn = document.createElement('button');
                    triggerBtn.type = 'button';
                    triggerBtn.className = 'rawnaq-spt-fab-trigger';
                    triggerBtn.setAttribute('aria-label', t('toggleNavActions', 'Toggle Navigation Actions'));
                    setStaticSvg(triggerBtn, SVG_FAB_TRIGGER);
                    fabWrapper.appendChild(triggerBtn);
                    var radialMenu = document.createElement('div');
                    radialMenu.className = 'rawnaq-spt-radial-menu';
                    var btnToc = document.createElement('button');
                    btnToc.type = 'button';
                    btnToc.className = 'rawnaq-spt-action-btn action-toc';
                    btnToc.setAttribute('title', t('toggleToc', 'Toggle Table of Contents'));
                    btnToc.setAttribute('aria-label', t('toggleToc', 'Toggle Table of Contents'));
                    setStaticSvg(btnToc, SVG_ACTION_TOC);
                    radialMenu.appendChild(btnToc);
                    var btnTop = document.createElement('button');
                    btnTop.type = 'button';
                    btnTop.className = 'rawnaq-spt-action-btn action-top';
                    btnTop.setAttribute('title', t('backToTop', 'Back to top'));
                    btnTop.setAttribute('aria-label', t('scrollToTop', 'Scroll to top of page'));
                    setStaticSvg(btnTop, SVG_ACTION_TOP);
                    radialMenu.appendChild(btnTop);
                    var btnCopy = document.createElement('button');
                    btnCopy.type = 'button';
                    btnCopy.className = 'rawnaq-spt-action-btn action-copy';
                    btnCopy.setAttribute('title', t('copyLink', 'Copy page link'));
                    btnCopy.setAttribute('aria-label', t('copyLink', 'Copy page link'));
                    setStaticSvg(btnCopy, SVG_ACTION_COPY);
                    radialMenu.appendChild(btnCopy);
                    fabWrapper.appendChild(radialMenu);
                    var toast = document.createElement('div');
                    toast.className = 'rawnaq-spt-toast-msg';
                    toast.setAttribute('role', 'status');
                    toast.setAttribute('aria-live', 'polite');
                    toast.hidden = true;
                    toast.textContent = t('linkCopied', 'Link Copied!');
                    fabWrapper.appendChild(toast);
                    root.appendChild(fabWrapper);
                    inst.fabWrapper = fabWrapper;
                    bindFabDocClick();
                    var btnToc = radialMenu.querySelector('.action-toc');
                    btnToc.addEventListener('click', function (e) {
                        e.stopPropagation();
                        toc.classList.toggle('is-sheet-open');
                        fabWrapper.classList.remove('is-active');
                    });
                    var btnTop = radialMenu.querySelector('.action-top');
                    btnTop.addEventListener('click', function (e) {
                        e.stopPropagation();
                        window.scrollTo({ top: 0, behavior: prefersReducedMotion() ? 'auto' : 'smooth' });
                        fabWrapper.classList.remove('is-active');
                    });
                    var btnCopy = radialMenu.querySelector('.action-copy');
                    btnCopy.addEventListener('click', function (e) {
                        e.stopPropagation();
                        var url = window.location.href.split('#')[0];
                        var showToast = function () {
                            toast.hidden = false;
                            toast.classList.add('show');
                            setTimeout(function () {
                                toast.classList.remove('show');
                                toast.hidden = true;
                            }, 2000);
                        };
                        if (navigator.clipboard && navigator.clipboard.writeText) {
                            navigator.clipboard.writeText(url).then(showToast).catch(function () {
                                fallbackCopy(url);
                                showToast();
                            });
                        } else {
                            fallbackCopy(url);
                            showToast();
                        }
                        fabWrapper.classList.remove('is-active');
                    });
                }
                if (dockAttached && fabWrapper) {
                    fabWrapper.hidden = true;
                    fabWrapper.style.display = 'none';
                }
            }
            root.classList.add('spt-bound');
            instances.push(inst);
            updateProgress(inst);
            updateActiveSection(inst);
            bindScroll();
        } catch (e) {
            console.error('[Rawnaq SPT] Setup failed:', e);
            if (inst.bar && inst.bar.parentNode) {
                inst.bar.parentNode.removeChild(inst.bar);
            }
            if (inst.ring && inst.ring.parentNode) {
                inst.ring.parentNode.removeChild(inst.ring);
            }
            if (inst.dockItem && inst.dockItem.parentNode) {
                inst.dockItem.parentNode.removeChild(inst.dockItem);
            }
            if (inst.fabWrapper && inst.fabWrapper.parentNode) {
                inst.fabWrapper.parentNode.removeChild(inst.fabWrapper);
            }
            root.classList.remove('spt-bound', 'is-dock-attached');
        }
    }
    function initAll() {
        destroyAll();
        document.querySelectorAll('.rawnaq-spt').forEach(initOne);
    }
    function hookElementor() {
        if (elementorHooked || !window.elementorFrontend || !elementorFrontend.hooks) {
            return;
        }
        elementorHooked = true;
        elementorFrontend.hooks.addAction(
            'frontend/element_ready/rawnaq_scroll_progress_toc.default',
            function ($scope) {
                if ($scope && $scope[0]) {
                    var el = $scope[0].classList.contains('rawnaq-spt')
                        ? $scope[0]
                        : $scope[0].querySelector('.rawnaq-spt');
                    if (el) {
                        initOne(el);
                    }
                }
            }
        );
    }
    function boot() {
        initAll();
        hookElementor();
    }
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', boot);
    } else {
        boot();
    }
    if (window.jQuery) {
        jQuery(window).on('elementor/frontend/init', hookElementor);
    }
    window.addEventListener('et_pb_after_init_modules', initAll);
})();